frappe.ui.form.on('Lead', {
    custom_aktueller_primärkontakt: function(frm) {
        if (frm.doc.custom_aktueller_primärkontakt) {
            frappe.db.get_doc('Contact', frm.doc.custom_aktueller_primärkontakt)
                .then(contact => {
                    // Übernahme der Salutation
                    if (contact.salutation) {
                        frm.set_value('salutation', contact.salutation);
                    }
                    // Übernahme von first_name, middle_name, last_name
                    if (contact.first_name) {
                        frm.set_value('first_name', contact.first_name);
                    }
                    if (contact.middle_name) {
                        frm.set_value('middle_name', contact.middle_name);
                    }
                    if (contact.last_name) {
                        frm.set_value('last_name', contact.last_name);
                    }
                });
        }
    },
    
    // Bei Änderungen in Lead soll das Skript ausgelöst werden
    refresh: function(frm) {
        frm.trigger('custom_aktueller_primärkontakt');
    }
});

frappe.ui.form.on('Lead', {
	validate: function(frm) {
	    if (frm.doc.custom_tel_zentrale)
	        {
            // Telefonnummer aus dem entsprechenden Feld abrufen
            let phoneNumber = frm.doc.custom_tel_zentrale;


            // Überprüfen, ob unzulässige Zeichen vorhanden sind (es passiert nix, aber ich lasse das jetzt erstmal drin.)
            const forbiddenChars = /[\(\)\[\]\/]/;
            if (forbiddenChars.test(phoneNumber)) {
                // frappe.throw ("Die Telefonnummer darf keine Klammern, Schrägstriche, Bindestriche oder Leerzeichen enthalten.");
                }


            // Überprüfen, ob die Telefonnummer mit einem + beginnt
            if (phoneNumber.charAt(0) !== '+') {
                frappe.throw ("Die Telefonnummer muss mit einem + und einer Länderkennung beginnen. Beispiel: +49123456");
                }



            // Entfernen aller nicht erlaubten Zeichen aus der Eingabe
            phoneNumber = phoneNumber.replace(/\s+/g, '');
            phoneNumber = phoneNumber.replace(/\-+/g, '');
            phoneNumber = phoneNumber.replace(/\(+/g, '');
            phoneNumber = phoneNumber.replace(/\)+/g, '');
            phoneNumber = phoneNumber.replace(/\[+/g, '');
            phoneNumber = phoneNumber.replace(/\]+/g, '');
            phoneNumber = phoneNumber.replace(/\/+/g, '');
            phoneNumber = phoneNumber.replace(/\+/g, '');
            // Feld beschreiben...
            frm.set_value('custom_tel_zentrale', '+' + phoneNumber);
	        }
    }
});

frappe.ui.form.on('Lead', {
    onload_post_render: function (frm) {
        frm.__original_custom_angebot_zugesendet = frm.doc.custom_angebot_zugesendet;
    },
    before_save: function (frm) {
        if (
            frm.__original_custom_angebot_zugesendet === 0 &&
            frm.doc.custom_angebot_zugesendet === 1
        ) {
            frappe.call({
                method: 'frappe.client.insert',
                args: {
                    doc: {
                        doctype: 'ToDo',
                        date: frappe.datetime.add_days(frappe.datetime.get_today(), 10),
                        allocated_to: 'k.reichegger@az-it.systems',
                        description: `WVL ${frm.doc.company_name} nach Angebot<br><br>Vor 10 Tagen wurde ein Angebot versendet.<br>Bitte nachhaken.<br>Das Angebot befindet sich links als Dateianhang im verknüpften Datensatz.`,
                        reference_type: 'Lead',
                        reference_name: frm.doc.name,
                        status: 'Open',
                        priority: 'Medium',
                        color: '#e74c3c',
                    }
                },
                callback: function (r) {
                    if (r.exc) {
                        frappe.msgprint(__('Das ToDo konnte nicht erstellt werden.'));
                    } else {
                        frappe.msgprint(__('Ein ToDo wurde erfolgreich erstellt.'));
                    }
                }
            });
        }
    },
    after_save: function (frm) {
        frm.__original_custom_angebot_zugesendet = frm.doc.custom_angebot_zugesendet;
    },
});

