frappe.ui.form.on("Payment Entry", {
    onload(frm) {

        // Nur setzen wenn leer
        if (!frm.doc.reference_no) {

            // Zufällige Zeichenfolge erzeugen
            const random_ref = Math.random()
                .toString(36)
                .substring(2, 12)
                .toUpperCase();

            frm.set_value("reference_no", random_ref);
        }

        // Falls reference_date ebenfalls Probleme macht
        if (!frm.doc.reference_date) {
            frm.set_value("reference_date", frm.doc.posting_date || frappe.datetime.get_today());
        }
    }
});

frappe.ui.form.on('ToDo', {
    onload: function(frm) {
        if (frm.doc.reference_name && frm.doc.reference_type) {
            frappe.call({
                method: "frappe.client.get",
                args: {
                    doctype: frm.doc.reference_type,
                    name: frm.doc.reference_name
                },
                callback: function(response) {
                    if (response.message) {
                        let linked_doc = response.message;

                        if (linked_doc.notes && linked_doc.notes.length > 0) {
                            // Sortiere die Notizen basierend auf dem 'added_on'-Zeitpunkt in absteigender Reihenfolge
                            linked_doc.notes.sort((a, b) => new Date(b.added_on) - new Date(a.added_on));

                            // Nimm die erste Notiz aus der sortierten Liste, die jetzt die neueste ist
                            let latest_note = linked_doc.notes[0];

                            if (latest_note) {
                                frm.set_value('custom_letzter_kommentar_an_verknüpften_daten', latest_note.note);
                                frm.save();
                            }
                        }
                    }
                }
            });
        }
    }
});

frappe.ui.form.on("Sales Invoice", {
    refresh(frm) {
        if (frm.__custom_email_doc_overridden) {
            return;
        }

        frm.__custom_email_doc_overridden = true;

        const original_email_doc = frm.email_doc.bind(frm);

        frm.email_doc = async function (
            message,
            subject,
            attachment,
            callback,
            print_format,
            print_letterhead
        ) {
            let recipient = "";

            try {
                if (frm.doc.contact_person) {
                    const result = await frappe.db.get_value(
                        "Contact",
                        frm.doc.contact_person,
                        ["email_id", "is_billing_contact"]
                    );

                    const contact = result?.message;

                    if (
                        contact &&
                        Number(contact.is_billing_contact) === 1 &&
                        contact.email_id
                    ) {
                        recipient = contact.email_id;
                    }
                }
            } catch (error) {
                console.error(
                    "Fehler beim Laden des Rechnungskontakts:",
                    error
                );
            }

            // Erst den ganz normalen ERPNext-Maildialog öffnen
            const result = original_email_doc(
                message,
                subject,
                attachment,
                callback,
                print_format,
                print_letterhead
            );

            // Danach nur den Empfänger austauschen
            if (recipient) {
                setTimeout(() => {
                    try {
                        const composer = frappe.views.communication_composer;

                        if (
                            composer &&
                            composer.dialog &&
                            composer.dialog.fields_dict &&
                            composer.dialog.fields_dict.recipients
                        ) {
                            composer.dialog.set_value(
                                "recipients",
                                recipient
                            );
                        }
                    } catch (error) {
                        console.error(
                            "Empfänger konnte im Maildialog nicht gesetzt werden:",
                            error
                        );
                    }
                }, 100);
            }

            return result;
        };
    }
});

frappe.ui.form.on("Sales Invoice", {
    async validate(frm) {
        if (!frm.doc.company || !frm.doc.items?.length) {
            return;
        }

        const response = await frappe.db.get_value(
            "Company",
            frm.doc.company,
            "default_income_account"
        );

        const default_income_account =
            response.message?.default_income_account;

        if (!default_income_account) {
            frappe.throw(
                __("No default income account is configured for company {0}.", [frm.doc.company])
            );
        }

        for (const row of frm.doc.items) {
            if (!row.income_account) {
                await frappe.model.set_value(
                    row.doctype,
                    row.name,
                    "income_account",
                    default_income_account
                );
            }
        }
    }
});
